def transform(grid):
    h, w = len(grid), len(grid[0])
    pts = [(r, c, grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] != 0]
    # The examples are periodic stripe patterns. Identify the stripe coordinate
    # (horizontal rows, NW-SE diagonals, or NE-SW diagonals) with fewest bands.
    coords = [
        (lambda r, c: r),
        (lambda r, c: c - r),
        (lambda r, c: r + c),
        (lambda r, c: c),
    ]
    scored = []
    for f in coords:
        bands = {f(r, c) for r, c, v in pts}
        scored.append((len(bands), f))
    _, stripe = min(scored, key=lambda x: x[0])
    clues = {}
    for r, c, v in pts:
        k = stripe(r, c)
        if k in clues and clues[k] != v:
            # Safety fallback: this orientation cannot represent the clues.
            return [row[:] for row in grid]
        clues[k] = v
    # Find the smallest period that is consistent with every observed band.
    p = 1
    while p <= max(h, w) * 2:
        residue_map = {}
        valid = True
        for k, v in clues.items():
            q = k % p
            if q in residue_map and residue_map[q] != v:
                valid = False
                break
            residue_map[q] = v
        if valid and len(residue_map) == p:
            break
        p += 1
    if p > max(h, w) * 2:
        return [row[:] for row in grid]
    return [[residue_map[stripe(r, c) % p] for c in range(w)] for r in range(h)]

